function drawZones(context, zones) {
  for (const [ink, outline] of zones) {
    context.fillStyle = palette[ink];
    context.fill(new Path2D(outline));
  }
}

function drawColorLayer(image, layer) {
  if (!image.complete || image.naturalWidth !== 2172 || image.naturalHeight !== 448) return false;
  layer.width = image.naturalWidth;
  layer.height = image.naturalHeight;
  const context = layer.getContext('2d');
  if (!context) return false;
  drawZones(context, westBank);
  context.save();
  context.translate(1050, 140);
  drawZones(context, eastBank);
  context.restore();
  context.globalCompositeOperation = 'destination-in';
  context.drawImage(image, 0, 0);
  context.globalCompositeOperation = 'source-over';
  return true;
}

export function watchHomeSkylineColor(stage, image, layer, canShow) {
  const widePointer = matchMedia('(min-width: 1181px) and (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)');
  let colorReady = false;
  let frame = 0;
  let transitionPointer = null;

  function clear() {
    cancelAnimationFrame(frame);
    frame = 0;
    transitionPointer = null;
    layer.classList.remove('is-lit');
  }

  function move(event) {
    if (!widePointer.matches || event.pointerType === 'touch' || !canShow()
      || event.target.closest('.mono-opening-foot')) {
      clear();
      return;
    }
    cancelAnimationFrame(frame);
    frame = requestAnimationFrame(() => {
      frame = 0;
      if (getComputedStyle(image).transform !== 'none') {
        clear();
        transitionPointer = event;
        return;
      }
      transitionPointer = null;
      const bounds = image.getBoundingClientRect();
      const { clientX, clientY } = event;
      if (clientX < bounds.left || clientX > bounds.right || clientY < bounds.top || clientY > bounds.bottom) {
        clear();
        return;
      }
      colorReady ||= drawColorLayer(image, layer);
      if (!colorReady) return;
      layer.style.setProperty('--skyline-light-x', `${clientX - bounds.left}px`);
      layer.classList.add('is-lit');
    });
  }

  function resumeAfterTransform(event) {
    if (event.propertyName === 'transform' && transitionPointer) move(transitionPointer);
  }

  stage.addEventListener('pointermove', move, { passive: true });
  stage.addEventListener('pointerleave', clear);
  stage.addEventListener('focusin', clear);
  image.addEventListener('transitionend', resumeAfterTransform);
  window.addEventListener('scroll', clear, { passive: true });
  window.addEventListener('blur', clear);
  window.addEventListener('resize', clear);
  widePointer.addEventListener('change', clear);
  return () => {
    clear();
    stage.removeEventListener('pointermove', move);
    stage.removeEventListener('pointerleave', clear);
    stage.removeEventListener('focusin', clear);
    image.removeEventListener('transitionend', resumeAfterTransform);
    window.removeEventListener('scroll', clear);
    window.removeEventListener('blur', clear);
    window.removeEventListener('resize', clear);
    widePointer.removeEventListener('change', clear);
  };
}
